refentry.refsect1:
&reftitle.description;
public Yaf_Request_AbstractnullYaf_Request_Abstract::setModuleName stringmodule boolformat_nametrue
Définit le nom du module dans la requête ; ceci est habituellement utilisé par un routeur personnalisé pour définir le nom du module résultant du routage.

  &reftitle.examples;

   Exemple avec Yaf_Request_Abstract::setModuleName


<?php
class AdminRouter extends Yaf_Route_Interface
{
    public function route(Yaf_Request_Abstract $request)
    {
        // Sert tout ce qui est sous /admin depuis le module Admin
        if (0 === strpos($request->getRequestUri(), "/admin")) {
            $request->setModuleName("Admin")
                    ->setControllerName("Dashboard")
                    ->setActionName("index");
            return true;
        }

        return false;
    }

    public function assemble(array $info, array $query = null) {}
}
?>
